            connectionName={CONST.POLICY.CONNECTIONS.NAME.NETSUITE}
            onSelectRow={updateSubsidiary}
            initiallyFocusedOptionKey={netsuiteConfig?.subsidiaryID ?? subsidiaryListSections?.[0]?.keyForList}
